23|
24|export function getControlModelsForEntitlement(manifest: IModelsControlManifest, entitlement: ChatEntitlement): IStringDictionary<IModelControlEntry> {
25|	return isProUser(entitlement) && entitlement !== ChatEntitlement.EDU ? manifest.paid : manifest.free;
26|}
27|
28|export function getModelPickerControlModels(
29|	manifest: IModelsControlManifest,
30|	entitlement: ChatEntitlement,
31|	models: readonly ILanguageModelChatMetadataAndIdentifier[],
32|): IStringDictionary<IModelControlEntry> {
33|	if (entitlement !== ChatEntitlement.Unknown) {
34|		return getControlModelsForEntitlement(manifest, entitlement);
35|	}
36|
37|	const availableModelIds = new Set(models
38|		.filter(model => !model.metadata.isBYOK && !model.metadata.byokModelIdentifier && !!model.metadata.targetChatSessionType)
39|		.map(model => model.metadata.id));
40|	const controlModels: IStringDictionary<IModelControlEntry> = {};
41|	for (const tier of [manifest.free, manifest.paid]) {
42|		for (const [id, entry] of Object.entries(tier)) {
43|			if (entry.featured && availableModelIds.has(id)) {
44|				controlModels[id] = { ...entry, exists: true };
45|			}
46|		}
47|	}
48|	return controlModels;
49|}
50|
51|export function shouldShowManageModelsAction(chatEntitlementService: IChatEntitlementService): boolean {
52|	return chatEntitlementService.clientByokEnabled ||
53|		chatEntitlementService.hasByokModels ||
54|		chatEntitlementService.entitlement === ChatEntitlement.Free ||
55|		chatEntitlementService.entitlement === ChatEntitlement.EDU ||
56|		chatEntitlementService.entitlement === ChatEntitlement.Pro ||
57|		chatEntitlementService.entitlement === ChatEntitlement.ProPlus ||
58|		chatEntitlementService.entitlement === ChatEntitlement.Max ||
59|		chatEntitlementService.entitlement === ChatEntitlement.Business ||
60|		chatEntitlementService.entitlement === ChatEntitlement.Enterprise ||
61|		chatEntitlementService.isInternal;
62|}
63|
64|export function createManageModelsAction(commandService: ICommandService): IActionWidgetDropdownAction {
65|	return {
66|		id: 'manageModels',
67|		enabled: true,
68|		checked: false,
69|		class: ThemeIcon.asClassName(Codicon.gear),
70|		tooltip: localize('chat.manageModels.tooltip', "Configure API keys, base URLs, and language models"),
71|		label: localize('chat.manageModels', "Configure API Key / Manage Models..."),
72|		run: async () => {
73|			// Prefer AIFront's BYOK configure flow when the extension is present.
74|			try {
75|				await commandService.executeCommand('shiyuncode.agent.manageModels');
76|				return;
77|			} catch {
78|				// fall through
79|			}
80|			await commandService.executeCommand(MANAGE_CHAT_COMMAND_ID);
81|		},
82|	};
83|}
84|
85|/** Builds the ordered model picker sections for the current presentation state. */
86|export function buildModelPickerItems(options: IBuildModelPickerItemsOptions): IActionListItem<IActionWidgetDropdownAction>[] {
87|	const unavailableItems = buildUnavailableStateItems(options);
88|	if (unavailableItems) {
89|		return unavailableItems;
90|	}
91|	return options.presentation.useGroupedModelPicker
92|		? buildGroupedModelItems(options)
93|		: buildFlatModelItems(options);
94|}
95|
96|export function getModelPickerAccessibilityProvider() {
97|	return {
98|		getAriaLabel(element: IActionListItem<IActionWidgetDropdownAction>) {
99|			if (element.kind !== ActionListItemKind.Action) {
100|				return null;
101|			}
102|			const description = element.ariaDescription ?? (typeof element.description === 'string' ? element.description : element.description?.value);
103|			return [element.label, element.badge, description].filter((part): part is string => !!part).join(', ');
104|		},
105|		isChecked(element: IActionListItem<IActionWidgetDropdownAction>) {
106|			if (element.isSectionToggle) {
107|				return undefined;
108|			}
109|			if (element.kind === ActionListItemKind.Action && !(element.item?.id && PICKER_COMMAND_ACTION_IDS.has(element.item.id))) {
110|				return !!element.item?.checked;
111|			}
112|			return undefined;
113|		},
114|		getRole: (element: IActionListItem<IActionWidgetDropdownAction>) => {
115|			if (element.isSectionToggle) {
116|				return 'menuitem';
117|			}
118|			switch (element.kind) {
119|				case ActionListItemKind.Action:
120|					return element.item?.id && PICKER_COMMAND_ACTION_IDS.has(element.item.id) ? 'menuitem' : 'menuitemradio';
121|				case ActionListItemKind.Separator:
122|				default:
123|					return 'separator';
124|			}
125|		},
126|		getWidgetRole: () => 'menu',
127|	} as const;
128|}
