30|export interface INewEditSessionActionContext {
31|
32|	/**
33|	 * An initial prompt to write to the chat.
34|	 */
35|	inputValue?: string;
36|
37|	/**
38|	 * Selects opening in agent mode or not. If not set, the current mode is used.
39|	 * This is ignored when coming from a chat view title context.
40|	 */
41|	agentMode?: boolean;
42|
43|	/**
44|	 * Whether the inputValue is partial and should wait for further user input.
45|	 * If false or not set, the prompt is sent immediately.
46|	 */
47|	isPartialQuery?: boolean;
48|}
49|
50|function isNewEditSessionActionContext(arg: unknown): arg is INewEditSessionActionContext {
51|	if (arg && typeof arg === 'object') {
52|		const obj = arg as Record<string, unknown>;
53|		if (obj.inputValue !== undefined && typeof obj.inputValue !== 'string') {
54|			return false;
55|		}
56|		if (obj.agentMode !== undefined && typeof obj.agentMode !== 'boolean') {
57|			return false;
58|		}
59|		if (obj.isPartialQuery !== undefined && typeof obj.isPartialQuery !== 'boolean') {
60|			return false;
61|		}
62|		return true;
63|	}
64|	return false;
65|}
