111|						group: '1_open',
112|						order: 1,
113|						when: ContextKeyExpr.and(
114|							ChatContextKeys.newChatButtonExperimentIcon.notEqualsTo('copilot'),
115|							ChatContextKeys.newChatButtonExperimentIcon.notEqualsTo('new-session'),
116|							ChatContextKeys.newChatButtonExperimentIcon.notEqualsTo('comment')
