160|						id: MenuId.ChatNewMenu,
161|						group: '1_open',
162|						order: 1,
163|						when: ChatContextKeys.newChatButtonExperimentIcon.isEqualTo(variant.iconValue)
164|					}]
165|				});
166|			}
167|
168|			async run(accessor: ServicesAccessor, ...args: unknown[]) {
169|				const executeCommandContext = isNewEditSessionActionContext(args[0]) ? args[0] : undefined;
170|				const context = getEditingSessionContext(accessor, args);
171|				await runNewChatAction(accessor, context, executeCommandContext);
172|			}
173|		});
174|	}
